/**
 * Simplified country outlines, for the loading screen.
 *
 * GENERATED — do not hand-edit. Built from Natural Earth's 110m admin-0
 * countries (public domain), reduced with Douglas–Peucker at a tolerance
 * scaled to each country's own span, so a small country keeps its shape
 * instead of collapsing to a triangle. Outer rings only, islands under 6% of
 * the largest dropped, coordinates rounded to one decimal (~11km, invisible at
 * the size this draws).
 *
 * Coordinates are plain longitude/latitude with the sign of y flipped, so the
 * paths read as an equirectangular map with north up and need no projection
 * at render time. `box` is that country's bounding box, which is what lets one
 * path serve both the faint world map and the zoomed outline.
 *
 * 169 of the app's 200 countries are here. The rest are microstates and small
 * island nations that Natural Earth at this scale either omits or renders too
 * small to recognise; the loading screen falls back to flag and name for them,
 * which is what it showed before this existed.
 *
 * Kept out of the main bundle: `CountryOutline` is lazy-loaded, so this ~21KB
 * gzipped only arrives when someone first opens a country.
 */
export interface Outline {
  /** SVG path data, already in screen orientation. */
  d: string
  /** [minX, minY, width, height] in the same units. */
  box: [number, number, number, number]
}

